INSERT INTO `futurerls` VALUES
(45, 1, 0, 'http://pic.ipicture.ru/uploads/081128/c7VPW3zCVa.jpg', '2008-11-28 09:10:28', 'Перевозчик 3 / Transporter 3', '27 ноября 2008 год', 'После своих последних приключений в Майами, Фрэнк Мартин решил поменять работу «перевозчика» на спокойную и уединенную жизнь во французской Ривьере. Но его планам не суждено было сбыться, когда к нему обратился бывший солдат из отряда «Дельта» Йонас Джонсон. Он рассказал, что по заказу корпорации «Ecocorp», занимающейся переработкой и утилизацией отходов, похищена Валентина — дочь украинского министра по охране окружающей среды Леонида Фазилева — чтобы путем вымогательства получить официальное разрешение для утилизации ядовитых отходов в Украине.\r\n\r\nТеперь задача героя — доставить Валентину через Европу в Одессу. Чтобы обеспечить выполнение задания, Джонсон одевает Фрэнку и Валентине электронные браслеты, которые могут взорваться, если их обладатели удаляются на 20 метров от автомобиля. Выполняя это задание, главному герою придется столкнуться с новыми опасностями, которые связаны не только с его заказом…', 5, '114'),
(46, 14, 0, 'http://i068.radikal.ru/0812/f3/993792e46acd.jpg', '2008-12-20 17:01:21', 'Серфер / Surfer, Dude', '2008', '[b]Название: [/b]Серфер\r\n[b]Оригинальное название: [/b]Surfer, Dude\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Комедия\r\n[b]Режиссер: [/b]С.Р. Биндлер\r\n[b]В ролях: [/b][color=#FF0000]Мэттью МакКонахи[/color], [color=#FF0000]Вуди Харрельсон[/color], [color=#FF0000]Уилли Нельсон[/color], Алекси Гилмор, К.Д. Ауберт, Джеффри Нордлинг, Сара Райт, Захари Найтон, Кассандра Хепберн, Тодд Стэшвик, Натан Филлипс, Рамон Родригез, Трэвис Фиммел\r\n\r\n[b]О фильме:[/b]\r\nСтив Аддингтон серфенгист от кончиков выгоревших волос до кончиков пальцев ног... босых, это его профессия и стиль жизни. В одно прохладное лето Стив возвращается в Малибу и находит свой родной город изменившимся до неузнаваемости. В городе властвует Госпожа Виртуальная Реальность, люди перестали жить своей жизнью, а все больше предпочитают наблюдать за происходящем по телевидению. Но самое главное - куда пропали волны? Полный штиль - это полоса отчаяния, неприятности преследуют Стива одна за другой. Удастся ли ему не свихнуться от этого плоского безумия, сумеет ли Стив не утонуть в 3D реальности и дождаться своей волны?\r\n', 5, '210'),
(47, 14, 0, 'http://i010.radikal.ru/0812/58/11a07343efb8.jpg', '2008-12-20 17:07:56', 'Гран Торино / Gran Torino ', 'Премьера (РФ): 19 февраля 2009', '[b]Название: [/b]Гран Торино\r\n[b]Оригинальное название: [/b]Gran Torino\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Боевик, триллер, драма\r\n[b]Режиссер: [/b][color=#FF0000]Клинт Иствуд[/color]\r\n[b]В ролях: [/b][color=#FF0000]Клинт Иствуд[/color], Кристофер Карли, Би Ванг, Эшни Хи, Брайан Хейли, Джеральдин Хьюз, Дрима Уолкер, Брайан Хоу, Джон Кэрролл Линч, Уильям Хилл\r\n\r\n[b]О фильме:[/b]\r\nВладелец коллекционной машины — старикан Уолт, трясущийся над авто и не подпускающий к ней никого на пушечный выстрел. Автомобиль, разумеется, бередит воображение местных подростков и один из них решается на угон…\r\n\r\n', 5, '209'),
(48, 11, 0, 'http://qtorrent.ru/descimages/1/39805.jpg', '2008-12-20 17:31:43', 'Джеймс Бонд 007: Квант милосердия / James Bond 007: Quantum of Solace', '19 декабря 2008 года', '[u]Информация о фильме[/u]\r\n[b]Название: [/b]Джеймс Бонд 007: Квант милосердия\r\n[b]Оригинальное название: [/b]James Bond 007: Quantum of Solace\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Боевик, Триллер, Приключения\r\n[b]Режиссер: [/b]Марк Форстер\r\n[b]В Ролях: [/b][color=darkorange][b]Дэниэл Крэйг, Ольга Куриленко[/b][/color], Матье Амальрик, Джуди Денч, Джанкарло Джаннини, Джемма Артертон, Джеффри Райт, Дэвид Харбор, Джеспер Кристенсен, Анатоль Таубман\r\n\r\n[b]О фильме:[/b]\r\nПосле предательства Веспер, агент 007 борется с желанием превратить последнее задание в личную вендетту. В поисках истины, Бонд и М допрашивают Мистера Уайта, от которого узнают, что шантажировавшая Веспер Организация намного сложнее и опаснее, чем можно было подумать. Судмедэксперты Mi6 устанавливают связь Веспер с анонимным банковским счётом на Гаити. Там Бонд случайно знакомится с боевой девушкой Камиллой, которая тоже жаждет мести. Через Камиллу Бонд выходит на Доминика Грина, жестокого бизнесмена и не последнего человека в Организации. Побывав в Австрии, Италии и Южной Америке, Бонд узнает о совместном заговоре Грина и генерала Медрано с целью установления контроля над мировыми запасами нефти. Используя возможности Организации и верных ему людей в ЦРУ и британской разведке, Грин обещает генералу свергнуть существующий режим в латиноамериканской стране, в обмен на, казалось бы, пустынный участок земли. Бонд прибегает к помощи старых друзей, чтобы установить истину. Чем ближе к установлению личности человека, толкнувшего Веспер на предательство, тем сложнее Бонду быть на шаг впереди ЦРУ, террористов и даже М, чтобы раскрыть злодейский план Грина и остановить его Организацию.\r\n\r\n[b]Перевод: [/b][b][color=yellowgreen]Дублированный[/b][/color]', 5, '201'),
(49, 14, 0, 'http://bt-star.ru/torrents/images/2000.jpg', '2008-12-20 17:40:38', 'Враг Государства #1: Легенда / Ennemi public n°1, L', 'Премьера РФ: 11 декабря 2008, Релиз на DVD: 19 февраля 2009', '[u]Информация о фильме[/u]\r\n[b]Название: [/b]Враг Государства  1: Легенда\r\n[b]Оригинальное название: [/b]Ennemi public n°1, L\'\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Боевик, триллер, драма, криминал, биография\r\n[b]Режиссер: [/b]Жан-Франсуа Рише\r\n[b]В Ролях: [/b][color=votebandark][b]Венсан Кассель[/b][/color], Людивин Санье, Матье Амальрик, Жерар Ланвен, Сэмюэл Ле Бьян, Оливье Гурме, Мишель Дюшоссуа, Мириам Буайе, Анна Консиньи, Жорж Вильсон\r\n\r\n[b]О фильме:[/b]\r\nЖак Мерин, великий французский гангстер, прославился у себя на родине больше, чем самая яркая кинозвезда. Авантюры Мерина всегда были головокружительно бесшабашными, отчаянно дерзкими и абсолютно непредсказуемыми по своему замыслу. Не зря его называли  человеком с тысячью лиц . Отправляясь на новое крупное  дело , он всегда изменял облик, делал пластические операции, использовал грим  перевоплощаясь до неузнаваемости.\r\nЕго боготворил народ, им восхищались женщины, а власти считали  врагом государства номер один ! А он и был именно таков. Его лихие  подвиги  и многочисленные побеги из тюрем, умопомрачительные любовные романы, феерические приключения и исключительно циничное, но по-галльски остроумное многолетнее издевательство над полицией   все это ныне превратилось для французов в подлинный народный эпос. Эпос о человеке, который умел быть настоящим героем. Или антигероем ', 5, '200'),
(50, 11, 0, 'http://bt-star.ru/torrents/images/2080.jpg', '2008-12-21 10:23:28', 'Подмена / Changeling', 'Премьера (РФ): 15 января 2009', '[u]Информация о фильме[/u]\r\n[b]Название: [/b]Подмена\r\n[b]Оригинальное название: [/b]Changeling\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Драма, криминал, детектив\r\n[b]Режиссер: [/b][color=darkorange]Клинт Иствуд[/color]\r\n[b]В Ролях: [/b][color=darkorange]Анджелина Джоли, Джон Малкович[/color], Гэтлин Гриффит, Мишель Мартин, Жан Деверо, Майкл Келли, Эрика Грант, Антония Беннетт, Керри Рэндлс, Фрэнк Вуд, Морган Иствуд\r\n\r\n[b]О фильме:[/b]\r\nДействие картины развивается в Лос-Анджелесе 20-х годов прошлого столетия. Обратившись в полицию с заявлением об исчезновении ребенка, главная героиня вскоре получает своего сына, но сообщает полицейским, что, несмотря на внешнее сходство, это не ее сын. Вместо помощи несчастная мать получает прописку в палате клиники для сумасшедших. Когда женщина решает, что ее настоящий сын оказался жертвой серийного убийцы, она начинает поиск правды собственными силами, вступает в борьбу с коррумпированными полицейскими и даже изменяет существовавшие в то время законы о душевнобольных.\r\n\r\n', 5, '208'),
(51, 14, 0, 'http://s45.radikal.ru/i109/0812/a8/88cef80994e6.jpg', '2008-12-21 12:49:32', 'Стиляги', 'Премьера РФ: 25 декабря', '[b]Название: [/b] Стиляги\r\n[b]Жанр:[/b] комедия, музыкальный\r\n[b]Производство:[/b] Россия, 2008 год\r\n[b]Продолжительность:[/b] 2 часа \r\n[b]Режиссер:[/b] Валерий Тодоровский\r\n[b]В ролях:[/b] Оксана Акиньшина, Антон Шагин, Максим Матвеев, Игорь Войнаровский, Екатерина Вилкова, Евегния Хиривская, Сергей Гармаш, Леонид Ярмольник, Олег Янковский, Алексей Горбунов\r\n\r\n[color=red]Премьера РФ: 25 декабря[/color]\r\n\r\n[b]О фильме:[/b]\r\nЭто история Москвы начала пятидесятых, в которой компании молодых людей приходится бороться за право быть не такими как все, слушать другую музыку, по-другому одеваться и конечно же любить.', 5, '254'),
(52, 14, 0, 'http://s52.radikal.ru/i137/0812/15/ad933ed24e31.jpg', '2008-12-21 12:57:41', 'Четыре Рождества / Four Christmases', 'Премьера (РФ): 18 декабря 2008, Релиз на DVD: 1 декабря 2009 ', '[b]Название: [/b]Четыре Рождества\r\n[b]Оригинальное название: [/b]Four Christmases\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Комедия\r\n[b]Режиссер: [/b]Сет Гордон\r\n[b]В ролях: [/b][color=#FF0000]Винс Вон[/color], [color=#FF0000]Риз Уизерспун[/color], Роберт Дювалл, Сисси Спейсек, Джон Войт, Джон Фавро, Мэри Стинберген, Дуайт Йокем, Тим МакГроу, Кристин Ченоуэт\r\n\r\n[b]О фильме:[/b]\r\nВлюбленная пара, Брэд и Кейт, пытается встретить Рождество вместе со своими родителями, но дело осложняется тем, что и его, и ее родители в разводе, поэтому им нужно за один день успеть в четыре разных места…', 5, '213'),
(53, 14, 0, 'http://s48.radikal.ru/i119/0812/3f/dba751ec1d48.jpg', '2008-12-21 13:01:49', 'Баксы', 'Премьера РФ: 2 октября 2008', '[b]Название: [/b]Баксы\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Драма\r\n[b]Режиссер: [/b]Гульшат Омарова\r\n[b]В ролях: [/b]Несипкуль Омарбекова, Фархад Аманкулов, Алмат Аянов, Асель Обутова, Саят Мерекенов, Олжас Нусупбаев\r\n\r\n[b]О фильме:[/b]\r\nЖизнь быстротечна и меняется каждый день. Но есть в нашей жизни вещи, которые были, остаются и останутся незыблемыми. Есть люди, которые существуют вне религий, вне социумов и вне времени. Люди, которые знают о жизни гораздо больше, чем остальные смертные - это шаманы, знахари, маги. Люди Природы, Духа, Силы. Фильм рассказывает о судьбе старухи Айдай, которая, как и все казахские баксы, может лечить людей, найти потерянную душу человека, сказать, где находится украденный скот... \"Баксы\" - по-казахски \"шаман\".\r\n\r\n[b]Выпущено: [/b]Германия / Россия / Франция / Казахстан, Кинокомпания CTB\r\n[b]Продолжительность: [/b]01:20:32', 5, '211'),
(54, 14, 0, 'http://s55.radikal.ru/i147/0812/a4/1084f6ff8e8e.jpg', '2008-12-21 14:44:29', 'Семь жизней / Seven Pounds', 'Премьера РФ: 15 января 2009, Релиз на DVD Февраль 2009 ', '[b]Название: [/b]Семь жизней \r\n[b]Оригинальное название: [/b]Seven Pounds\r\n[b]Год выхода: [/b]2008\r\n[b]Жанр: [/b]Драма\r\n[b]Режиссер: [/b]Габриэле Муччино\r\n[b]В ролях: [/b][color=#FF0000]Уилл Смит[/color], [color=#FF0000]Розарио Доусон[/color], [color=#FF0000]Вуди Харрельсон[/color], Майкл Или, Бэрри Пеппер, Элпидия Каррильо, Робин Ли, Джо Нуньес, Билл Смитрович, Тим Келлехер\r\n\r\n[b]О фильме:[/b]\r\nПытаясь исправить ошибки прошлого, Бен решает помогать совершенно незнакомым людям. Но все сильно осложняется, когда он встречает смертельно больную Эмили и влюбляется в нее…\r\n\r\n[b]Выпущено: [/b]США, Columbia Pictures\r\n[b]Продолжительность: [/b]02:03:04', 5, '212'),
(55, 1, 0, 'http://www.filmz.ru/films_files/posters/medium/m_6965.jpg', '2008-12-22 19:49:54', 'Приключения Десперо', '25 Декабря 2008', '[b]Название:[/b] Приключения Десперо\r\n[b]Оригинальное название:[/b] The Tale of Despereaux\r\n[b]Режиссер:[/b] Сэм Фелл, Роберт Стивенхейген\r\n\r\n[b]Описание:[/b] Это история о трёх существах, менее всего подходящих на роли героев — Мыши, предпочитающей читать книги, вместо того, чтобы есть их; Крысы, плетущей интриги ради того, чтобы навсегда покинуть сырую темницу; и лопоухой девочки — чьи судьбы переплетаются с неисповедимыми путями Принцессы.', 5, '220'),
(56, 14, 0, 'http://www.film.ru/img/afisha/LUBVMRK2/posters/poster2.jpg', '2008-12-25 18:59:26', 'Любовь-морковь 2', 'Премьера В России:23.12.2008', '[b]Название: [/b] Любовь-морковь 2\r\n[b]Год выхода: [/b]2009\r\n[b]Жанр: [/b] комедия / мелодрама \r\n[b]Режиссер: [/b] Максим Пежемский \r\n[b]В ролях: [/b] Гоша Куценко, Кристина Орбакайте, Лидия Вележева, Кирилл Плетнев, Ольга Орлова, Денис Парамонов, Алина Булынка, Андрей Ургант, Дарья Дроздовская \r\n\r\n\r\n[b]О фильме:[/b]\r\nДесять лет назад супруги Голубевы проверили свои чувства на прочность, поменявшись телами. Теперь они — папа Андрей и мама Марина. В их семье растут близнецы: мальчик и девочка — Глеб и Светочка.\r\n\r\nЖизнь супругов налажена, карьера головокружительна, а день расписан по часам. Они уже плохо помнят, что дети больше любят живых собак, чем искусственных, и что друзья родителей не лучшая компания в день рожденья. Они забыли, что любовь и внимание дороже денег. Чтобы вернуть все на свои места, нужно опять поменять всех местами, — решит доктор Коган и навестит своих старых приятелей Голубевых.\r\n\r\nА поутру они проснутся — Глеб и Света в родительской спальне, Андрей и Марина — в детской. Пока \"маленькие\" Голубевы будут поражать одноклассников и учителей познаниями, их \"взрослые\" дети едва не поставят крест на карьере родителей и лишат семью крова. Андрею и Марине светит детский дом, а Свете и Глебу — сумасшедший. Но Голубевы не сдаются!\r\n\r\nМенеджеры по персоналу узнают, как может справиться с работой рекламного \"чебурека\" блестящий искусствовед, и стоит ли давать бывшим юристам в руки швабру. Злобная няня сгорит на работе, а риэлтор попробует продать дом на кладбище со скользкими лестницами. Чтобы \"прийти в себя\", вернуть свой дом и доброе имя Голубевым придется сплотиться, разоблачить злоумышленников, вернуть легендарный бриллиант и найти ключ от банковской ячейки, где деньги лежат...\r\n\r\n[b]Продолжительность: [/b] 98 мин.', 5, '253');
